CREATE TABLE trunked_identity_scope (     scope_id INTEGER PRIMARY KEY AUTOINCREMENT,     scope_token TEXT NOT NULL UNIQUE,     protocol_code INTEGER NOT NULL CHECK(protocol_code IN (1, 3, 4)),     scope_kind_code INTEGER NOT NULL CHECK(scope_kind_code IN (1, 2)),     identity_domain_code INTEGER NOT NULL DEFAULT 0 CHECK(identity_domain_code IN (0, 1, 2)),     p25_system_key INTEGER UNIQUE REFERENCES p25_system(system_key) ON DELETE CASCADE,     first_seen_ms INTEGER NOT NULL,     last_seen_ms INTEGER NOT NULL,     CHECK(         (scope_kind_code = 1 AND protocol_code = 1 AND p25_system_key IS NOT NULL)         OR         (scope_kind_code = 2 AND protocol_code IN (3, 4) AND p25_system_key IS NULL)     ) );
