CREATE TABLE trunked_identity_scope_context (     context_id INTEGER PRIMARY KEY REFERENCES receiver_context(id) ON DELETE CASCADE,     scope_id INTEGER NOT NULL REFERENCES trunked_identity_scope(scope_id) ON DELETE CASCADE,     first_seen_ms INTEGER NOT NULL,     last_seen_ms INTEGER NOT NULL ) WITHOUT ROWID ;
