CREATE TABLE trunked_identity_summary (     scope_id INTEGER NOT NULL REFERENCES trunked_identity_scope(scope_id) ON DELETE CASCADE,     identity_kind_code INTEGER NOT NULL CHECK(identity_kind_code IN (1, 2, 3)),     identity_id INTEGER NOT NULL CHECK(identity_id > 0),     p25_identity_state_code INTEGER NOT NULL DEFAULT 0         CHECK(p25_identity_state_code IN (0, 1, 2, 3)),     p25_home_wacn INTEGER,     p25_home_system_id INTEGER,     p25_home_talkgroup_id INTEGER,     first_seen_ms INTEGER NOT NULL,     last_seen_ms INTEGER NOT NULL,     acknowledge_count INTEGER NOT NULL DEFAULT 0 CHECK(acknowledge_count >= 0), active_count INTEGER NOT NULL DEFAULT 0 CHECK(active_count >= 0), busy_count INTEGER NOT NULL DEFAULT 0 CHECK(busy_count >= 0), call_count INTEGER NOT NULL DEFAULT 0 CHECK(call_count >= 0), check_count INTEGER NOT NULL DEFAULT 0 CHECK(check_count >= 0), check_ack_count INTEGER NOT NULL DEFAULT 0 CHECK(check_ack_count >= 0), continue_count INTEGER NOT NULL DEFAULT 0 CHECK(continue_count >= 0), data_count INTEGER NOT NULL DEFAULT 0 CHECK(data_count >= 0), denial_count INTEGER NOT NULL DEFAULT 0 CHECK(denial_count >= 0), emergency_count INTEGER NOT NULL DEFAULT 0 CHECK(emergency_count >= 0), gps_count INTEGER NOT NULL DEFAULT 0 CHECK(gps_count >= 0), grant_count INTEGER NOT NULL DEFAULT 0 CHECK(grant_count >= 0), join_count INTEGER NOT NULL DEFAULT 0 CHECK(join_count >= 0), logout_count INTEGER NOT NULL DEFAULT 0 CHECK(logout_count >= 0), page_count INTEGER NOT NULL DEFAULT 0 CHECK(page_count >= 0), patch_count INTEGER NOT NULL DEFAULT 0 CHECK(patch_count >= 0), patch_cancel_count INTEGER NOT NULL DEFAULT 0 CHECK(patch_cancel_count >= 0), patch_create_count INTEGER NOT NULL DEFAULT 0 CHECK(patch_create_count >= 0), queued_count INTEGER NOT NULL DEFAULT 0 CHECK(queued_count >= 0), register_count INTEGER NOT NULL DEFAULT 0 CHECK(register_count >= 0), request_count INTEGER NOT NULL DEFAULT 0 CHECK(request_count >= 0), status_count INTEGER NOT NULL DEFAULT 0 CHECK(status_count >= 0), unknown_count INTEGER NOT NULL DEFAULT 0 CHECK(unknown_count >= 0) ,     source_call_count INTEGER NOT NULL DEFAULT 0 CHECK(source_call_count >= 0),     target_call_count INTEGER NOT NULL DEFAULT 0 CHECK(target_call_count >= 0),     encrypted_count INTEGER NOT NULL DEFAULT 0 CHECK(encrypted_count >= 0),     recorded_count INTEGER NOT NULL DEFAULT 0 CHECK(recorded_count >= 0),     streamed_count INTEGER NOT NULL DEFAULT 0 CHECK(streamed_count >= 0),     last_counterpart_kind_code INTEGER CHECK(last_counterpart_kind_code IN (1, 2, 3)),     last_counterpart_id INTEGER CHECK(last_counterpart_id > 0),     last_encryption_algorithm_id INTEGER,     last_encryption_key_id INTEGER,     last_talker_alias TEXT,     last_talker_alias_seen_ms INTEGER,     PRIMARY KEY(scope_id, identity_kind_code, identity_id),     CHECK(         (last_counterpart_kind_code IS NULL AND last_counterpart_id IS NULL)         OR         (last_counterpart_kind_code IS NOT NULL AND last_counterpart_id IS NOT NULL)     ),     CHECK(         (p25_identity_state_code = 2             AND p25_home_wacn BETWEEN 0 AND 1048575             AND p25_home_system_id BETWEEN 0 AND 4095             AND p25_home_talkgroup_id BETWEEN 1 AND 65534)         OR         (p25_identity_state_code != 2             AND p25_home_wacn IS NULL             AND p25_home_system_id IS NULL             AND p25_home_talkgroup_id IS NULL)     ) ) WITHOUT ROWID ;
