CREATE TABLE trunked_radio_affiliation (     scope_id INTEGER NOT NULL REFERENCES trunked_identity_scope(scope_id) ON DELETE CASCADE,     radio_id INTEGER NOT NULL CHECK(radio_id > 0),     talkgroup_id INTEGER NOT NULL CHECK(talkgroup_id > 0),     confirmed_at_ms INTEGER NOT NULL,     PRIMARY KEY(scope_id, radio_id) ) WITHOUT ROWID ;
CREATE TABLE trunked_radio_presence_lifecycle (     scope_id INTEGER NOT NULL REFERENCES trunked_identity_scope(scope_id) ON DELETE CASCADE,     radio_id INTEGER NOT NULL CHECK(radio_id > 0),     cleared_at_ms INTEGER NOT NULL,     PRIMARY KEY(scope_id, radio_id) ) WITHOUT ROWID ;
CREATE TABLE trunked_radio_site_presence (     scope_id INTEGER NOT NULL REFERENCES trunked_identity_scope(scope_id) ON DELETE CASCADE,     radio_id INTEGER NOT NULL CHECK(radio_id > 0),     context_id INTEGER NOT NULL         REFERENCES trunked_identity_scope_context(context_id) ON DELETE CASCADE,     evidence_code INTEGER NOT NULL CHECK(evidence_code IN (1, 2)),     confirmed_at_ms INTEGER NOT NULL,     PRIMARY KEY(scope_id, radio_id) ) WITHOUT ROWID ;
CREATE TABLE trunked_radio_talkgroup_summary (     scope_id INTEGER NOT NULL REFERENCES trunked_identity_scope(scope_id) ON DELETE CASCADE,     radio_id INTEGER NOT NULL CHECK(radio_id > 0),     talkgroup_id INTEGER NOT NULL CHECK(talkgroup_id > 0),     target_kind_code INTEGER NOT NULL CHECK(target_kind_code IN (1, 3)),     first_seen_ms INTEGER NOT NULL,     last_seen_ms INTEGER NOT NULL,     acknowledge_count INTEGER NOT NULL DEFAULT 0 CHECK(acknowledge_count >= 0), active_count INTEGER NOT NULL DEFAULT 0 CHECK(active_count >= 0), busy_count INTEGER NOT NULL DEFAULT 0 CHECK(busy_count >= 0), call_count INTEGER NOT NULL DEFAULT 0 CHECK(call_count >= 0), check_count INTEGER NOT NULL DEFAULT 0 CHECK(check_count >= 0), check_ack_count INTEGER NOT NULL DEFAULT 0 CHECK(check_ack_count >= 0), continue_count INTEGER NOT NULL DEFAULT 0 CHECK(continue_count >= 0), data_count INTEGER NOT NULL DEFAULT 0 CHECK(data_count >= 0), denial_count INTEGER NOT NULL DEFAULT 0 CHECK(denial_count >= 0), emergency_count INTEGER NOT NULL DEFAULT 0 CHECK(emergency_count >= 0), gps_count INTEGER NOT NULL DEFAULT 0 CHECK(gps_count >= 0), grant_count INTEGER NOT NULL DEFAULT 0 CHECK(grant_count >= 0), join_count INTEGER NOT NULL DEFAULT 0 CHECK(join_count >= 0), logout_count INTEGER NOT NULL DEFAULT 0 CHECK(logout_count >= 0), page_count INTEGER NOT NULL DEFAULT 0 CHECK(page_count >= 0), patch_count INTEGER NOT NULL DEFAULT 0 CHECK(patch_count >= 0), patch_cancel_count INTEGER NOT NULL DEFAULT 0 CHECK(patch_cancel_count >= 0), patch_create_count INTEGER NOT NULL DEFAULT 0 CHECK(patch_create_count >= 0), queued_count INTEGER NOT NULL DEFAULT 0 CHECK(queued_count >= 0), register_count INTEGER NOT NULL DEFAULT 0 CHECK(register_count >= 0), request_count INTEGER NOT NULL DEFAULT 0 CHECK(request_count >= 0), status_count INTEGER NOT NULL DEFAULT 0 CHECK(status_count >= 0), unknown_count INTEGER NOT NULL DEFAULT 0 CHECK(unknown_count >= 0) ,     encrypted_count INTEGER NOT NULL DEFAULT 0 CHECK(encrypted_count >= 0),     recorded_count INTEGER NOT NULL DEFAULT 0 CHECK(recorded_count >= 0),     streamed_count INTEGER NOT NULL DEFAULT 0 CHECK(streamed_count >= 0),     last_encryption_algorithm_id INTEGER,     last_encryption_key_id INTEGER,     PRIMARY KEY(scope_id, radio_id, talkgroup_id, target_kind_code) ) WITHOUT ROWID ;
CREATE TABLE trunked_site_channel_summary (     guid TEXT NOT NULL,     channel_number INTEGER NOT NULL,     inbound_channel_number INTEGER NOT NULL,     timeslot INTEGER NOT NULL,     frequency_hz INTEGER NOT NULL,     uplink_hz INTEGER,     role_flags INTEGER NOT NULL DEFAULT 0,     first_seen_ms INTEGER NOT NULL,     last_seen_ms INTEGER NOT NULL,     observation_count INTEGER NOT NULL DEFAULT 1,     PRIMARY KEY(guid, channel_number, inbound_channel_number, timeslot, frequency_hz),     FOREIGN KEY(guid) REFERENCES trunked_site_snapshot(guid) ON DELETE CASCADE,     CHECK(last_seen_ms >= first_seen_ms),     CHECK(observation_count > 0) ) WITHOUT ROWID ;
CREATE TABLE trunked_site_neighbor_summary (     guid TEXT NOT NULL,     variant_code INTEGER NOT NULL,     identity_domain_code INTEGER NOT NULL,     network_id INTEGER NOT NULL,     system_id INTEGER NOT NULL,     site_id INTEGER NOT NULL,     channel_number INTEGER NOT NULL,     frequency_hz INTEGER NOT NULL,     status_flags INTEGER NOT NULL DEFAULT 0,     first_seen_ms INTEGER NOT NULL,     last_seen_ms INTEGER NOT NULL,     observation_count INTEGER NOT NULL DEFAULT 1,     PRIMARY KEY(guid, variant_code, identity_domain_code, network_id, system_id, site_id,         channel_number, frequency_hz),     FOREIGN KEY(guid) REFERENCES trunked_site_snapshot(guid) ON DELETE CASCADE,     CHECK(last_seen_ms >= first_seen_ms),     CHECK(observation_count > 0) ) WITHOUT ROWID ;
CREATE TABLE trunked_site_snapshot (     guid TEXT PRIMARY KEY,     snapshot_hash TEXT NOT NULL,     protocol_code INTEGER NOT NULL,     variant_code INTEGER NOT NULL DEFAULT 0,     identity_domain_code INTEGER NOT NULL DEFAULT 0,     configured_system TEXT,     channel_name TEXT,     alias_list_name TEXT,     decoder TEXT,     network_id INTEGER,     system_id INTEGER,     site_id INTEGER,     ran INTEGER,     model_code INTEGER,     brand_code INTEGER,     mode_code INTEGER,     channel_type_code INTEGER,     color_code_ts1 INTEGER,     color_code_ts2 INTEGER,     current_repeater INTEGER,     service_flags INTEGER,     failure_code INTEGER,     primary_frequency_hz INTEGER,     current_control_hz INTEGER,     first_seen_ms INTEGER NOT NULL,     last_seen_ms INTEGER NOT NULL,     observation_count INTEGER NOT NULL DEFAULT 1,     CHECK(protocol_code IN (3, 4)),     CHECK(last_seen_ms >= first_seen_ms),     CHECK(observation_count > 0) );
