CREATE VIEW alias_talkgroup AS SELECT alias.id AS alias_id,        alias.protocol,        alias.value,        alias.min_value,        alias.max_value,        CASE WHEN alias.matcher_type = 'TALKGROUP_RANGE' THEN 1 ELSE 0 END AS ranged,        alias_list.name AS alias_list_name FROM alias JOIN alias_list ON alias_list.id = alias.alias_list_id WHERE alias.matcher_type IN (       'TALKGROUP',       'TALKGROUP_RANGE'   );
CREATE VIEW alias_radio AS SELECT alias.id AS alias_id,        alias.protocol,        alias.value,        alias.min_value,        alias.max_value,        CASE WHEN alias.matcher_type = 'RADIO_ID_RANGE' THEN 1 ELSE 0 END AS ranged,        alias_list.name AS alias_list_name FROM alias JOIN alias_list ON alias_list.id = alias.alias_list_id WHERE alias.matcher_type IN (       'RADIO_ID',       'RADIO_ID_RANGE'   );
