CREATE VIEW p25_activity_event_resolved AS SELECT     a.id,     rc.context_key,     rc.guid,     CASE rc.kind_code WHEN 1 THEN 'TRUNKED_SITE' WHEN 2 THEN 'CONVENTIONAL_P25' WHEN 3 THEN 'CONVENTIONAL_DMR' WHEN 4 THEN 'CONVENTIONAL_NXDN' WHEN 10 THEN 'CONVENTIONAL_ANALOG' ELSE NULL END AS channel_kind,     a.observed_at_ms,     CASE rc.protocol_code WHEN 1 THEN 'APCO25' WHEN 2 THEN 'APCO25_PHASE2' WHEN 3 THEN 'DMR' WHEN 4 THEN 'NXDN' WHEN 10 THEN 'NBFM' ELSE 'UNKNOWN' END AS protocol,     CASE a.action_code WHEN 1 THEN 'ACKNOWLEDGE' WHEN 2 THEN 'ACTIVE' WHEN 3 THEN 'BUSY' WHEN 4 THEN 'CALL' WHEN 5 THEN 'CHECK' WHEN 6 THEN 'CHECK_ACK' WHEN 7 THEN 'CONTINUE' WHEN 8 THEN 'DATA' WHEN 9 THEN 'DENIAL' WHEN 10 THEN 'EMERGENCY' WHEN 11 THEN 'GPS' WHEN 12 THEN 'GRANT' WHEN 13 THEN 'JOIN' WHEN 14 THEN 'LOGOUT' WHEN 15 THEN 'PAGE' WHEN 16 THEN 'PATCH' WHEN 17 THEN 'PATCH_CANCEL' WHEN 18 THEN 'PATCH_CREATE' WHEN 19 THEN 'QUEUED' WHEN 20 THEN 'REGISTER' WHEN 21 THEN 'REQUEST' WHEN 22 THEN 'STATUS' WHEN 23 THEN 'UNKNOWN' ELSE 'UNKNOWN' END AS action,     CASE a.event_type_code WHEN 1 THEN 'AFFILIATE' WHEN 2 THEN 'ANNOUNCEMENT' WHEN 3 THEN 'ACKNOWLEDGE' WHEN 4 THEN 'AUTOMATIC_REGISTRATION_SERVICE' WHEN 5 THEN 'CALL' WHEN 6 THEN 'CALL_ENCRYPTED' WHEN 7 THEN 'CALL_GROUP' WHEN 8 THEN 'CALL_GROUP_ENCRYPTED' WHEN 9 THEN 'CALL_PATCH_GROUP' WHEN 10 THEN 'CALL_PATCH_GROUP_ENCRYPTED' WHEN 11 THEN 'CALL_ALERT' WHEN 12 THEN 'CALL_DETECT' WHEN 13 THEN 'CALL_IN_PROGRESS' WHEN 14 THEN 'CALL_DO_NOT_MONITOR' WHEN 15 THEN 'CALL_END' WHEN 16 THEN 'CALL_INTERCONNECT' WHEN 17 THEN 'CALL_INTERCONNECT_ENCRYPTED' WHEN 18 THEN 'CALL_UNIQUE_ID' WHEN 19 THEN 'CALL_UNIT_TO_UNIT' WHEN 20 THEN 'CALL_UNIT_TO_UNIT_ENCRYPTED' WHEN 21 THEN 'CALL_NO_TUNER' WHEN 22 THEN 'CALL_TIMEOUT' WHEN 23 THEN 'CELLOCATOR' WHEN 24 THEN 'COMMAND' WHEN 25 THEN 'DATA_CALL' WHEN 26 THEN 'DATA_CALL_ENCRYPTED' WHEN 27 THEN 'DATA_PACKET' WHEN 28 THEN 'DEREGISTER' WHEN 29 THEN 'DYNAMIC_REGROUP' WHEN 30 THEN 'EMERGENCY' WHEN 31 THEN 'FUNCTION' WHEN 32 THEN 'GPS' WHEN 33 THEN 'ICMP_PACKET' WHEN 34 THEN 'ID_ANI' WHEN 35 THEN 'ID_UNIQUE' WHEN 36 THEN 'IP_PACKET' WHEN 37 THEN 'LRRP' WHEN 38 THEN 'NOTIFICATION' WHEN 39 THEN 'PAGE' WHEN 40 THEN 'QUERY' WHEN 41 THEN 'RADIO_CHECK' WHEN 42 THEN 'RADIO_REGISTRATION_SERVICE' WHEN 43 THEN 'REGISTER' WHEN 44 THEN 'REGISTER_ESN' WHEN 45 THEN 'REQUEST' WHEN 46 THEN 'RESPONSE' WHEN 47 THEN 'RESPONSE_PACKET' WHEN 48 THEN 'SDM' WHEN 49 THEN 'SMS' WHEN 50 THEN 'STATION_ID' WHEN 51 THEN 'STATUS' WHEN 52 THEN 'TEXT_MESSAGE' WHEN 53 THEN 'UDP_PACKET' WHEN 54 THEN 'UNKNOWN_PACKET' WHEN 55 THEN 'XCMP' WHEN 56 THEN 'UNKNOWN' WHEN 57 THEN 'DENIAL' ELSE NULL END AS event_type,     a.source_radio_id,     a.target_id,     CASE a.target_kind_code WHEN 1 THEN 'TALKGROUP' WHEN 2 THEN 'RADIO' WHEN 3 THEN 'PATCH_GROUP' ELSE NULL END AS target_kind,     a.frequency_hz,     CASE         WHEN a.lcn_band IS NOT NULL AND a.lcn_number IS NOT NULL         THEN a.lcn_band || '-' || a.lcn_number         ELSE NULL     END AS lcn,     a.timeslot,     a.encrypted,     a.encryption_algorithm_id,     a.encryption_key_id,     a.context_id,     rc.kind_code AS channel_kind_code,     rc.protocol_code,     a.action_code,     a.event_type_code,     a.target_kind_code,     rc.channel_name AS resolved_channel_name,     rc.alias_list_name AS resolved_alias_list_name,     rc.decoder AS resolved_decoder,     rc.system_key AS resolved_system_key,     ps.wacn AS resolved_wacn,     ps.system_id AS resolved_system_id,     rc.nac AS resolved_nac,     rc.rfss AS resolved_rfss,     rc.site AS resolved_site,     rc.current_control_hz AS resolved_current_control_hz FROM p25_activity_event a LEFT JOIN receiver_context rc ON rc.id = a.context_id LEFT JOIN p25_system ps ON ps.system_key = rc.system_key;
COMMIT;
